-- Migration 20260901193000 · level:secondary-sales · lane:A1 · writes:aq_event_map.sg_event_id · reads:events,sg_events_canonical · pre:20260901185000
--
-- Backfill aq_event_map.sg_event_id from the AQ 5.1.27 export, via the EVO mapper's rule.
--
-- WHY. The export (218,668 future events) carries a SeatGeek event id but NO TEvo
-- event id -- its `Trade Desk Event Id` is a different id space that merely overlaps
-- TEvo's numerically (0/856 matched on the 1,548 rows where hub and export overlap).
-- So the export cannot be joined to our catalogue on an id. Chaining through SeatGeek
-- instead is also a dead end as a pure lookup: of the 1,405 hub rows that carry an
-- sg_event_id but no tevo_event_id, sg_events_canonical resolves exactly 2 -- the rows
-- it could link, it already linked.
--
-- What DOES work is running the mapper rather than a lookup. This applies
-- match_tevo_to_sg_canonical()'s tier-2 rule (venue name exact, event time within
-- +/-6h) between our 5,410 unlinked future TEvo events and the export's 77,148 rows
-- that carry a SeatGeek id, then filters the result by name agreement.
--
-- SCOPE. One column, on rows where it is currently NULL -- nothing is overwritten.
--
-- GUARDS (venue+date alone is not safe; this is the Arthur Ashe lesson).
--   * 262 TEvo events matched >1 distinct SeatGeek id in the window -> dropped, not
--     guessed. Multi-session venues (US Open, festival stages) live here.
--   * Name agreement must be >=0.60 (max of token-Jaccard and SequenceMatcher), OR
--     one title's tokens must be a subset of the other's. The subset rule rescues 147
--     headliner/support pairs ("Gorillaz" vs "Gorillaz with Little Simz and Deltron
--     3030"); the floor rejects same-venue same-night collisions that are genuinely
--     different shows -- "Tate McRae with Zara Larsson" vs "Lily Allen",
--     "Armand Hammer" vs "Paris Paloma", Cup Series vs the ARCA support race.
--   * Season-ticket / parking / hospitality packages are excluded outright: a TEvo
--     season package is not a single game, and venue+date would happily bind
--     "2026 Pittsburgh Steelers Season Tickets" to one Panthers fixture.
--   * Any pair whose tevo id or sg id is not 1:1 across the accepted set is dropped.
--   * 46 matches failed these checks and are deliberately left unmapped.
--
-- 3,576 venue+date matches -> 3498 written. Verification query at the foot.

BEGIN;

CREATE TEMP TABLE _sg_backfill(tevo_event_id bigint PRIMARY KEY, sg_event_id bigint UNIQUE) ON COMMIT DROP;


-- Only fill blanks, and never hand an sg_event_id to a second hub row.
UPDATE public.aq_event_map m
   SET sg_event_id = b.sg_event_id
  FROM _sg_backfill b
 WHERE m.tevo_event_id = b.tevo_event_id
   AND m.sg_event_id IS NULL
   AND NOT EXISTS (
     SELECT 1 FROM public.aq_event_map x
      WHERE x.sg_event_id = b.sg_event_id AND x.id <> m.id
   );

COMMIT;

-- Verification (expect sg coverage up by ~3.4k, and zero duplicated sg ids):
--   SELECT count(*) FILTER (WHERE sg_event_id IS NOT NULL) AS with_sg, count(*) FROM aq_event_map;
--   SELECT sg_event_id, count(*) FROM aq_event_map WHERE sg_event_id IS NOT NULL
--     GROUP BY 1 HAVING count(*) > 1;
